import{_ as s,l as i,o as a,c as n,v as t,p as c,x as r,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"穷尽性检查","description":"","frontmatter":{"title":"穷尽性检查","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exhaustiveness-check.md","filePath":"cs/exhaustiveness-check.md","lastUpdated":1789023840000}'),h={name:"cs/exhaustiveness-check.md"};function _(u,e,m,E,A,f){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="穷尽性检查" tabindex="-1">穷尽性检查 <a class="header-anchor" href="#穷尽性检查" aria-label="Permalink to &quot;穷尽性检查&quot;">​</a></h1><div class="epigraph"><p>若存在一个值，使得所有子句都失败，则匹配不穷尽。无用子句是永远被前面挡住的模式。二者都可在构造子有限时判定。</p><footer>—— 据 Maranget, Warnings for Pattern Matching, 2007；Peyton Jones 等 GHC 诊断；Pierce 对 case 穷尽的讨论整理</footer></div><p>上一课<a href="/cs/adt-pattern-compile">模式匹配编译</a>把子句变成判定树。缺口是<strong>静态诊断</strong>：没写 <code>Nothing</code>、或 <code>x::_</code> 挡住了后面的 <code>[]</code>。Maranget 用「反例值」与矩阵的有用性。本课钉检查，不重写分派代码生成。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译判定树时，默认边若到达「无子句」则运行时失败（ML 的 <code>Match</code> 异常）。语言可拒绝不穷尽，或警告。算法：在子句矩阵上求是否存在向量 \\(v\\) 逃过所有行；若存在，pretty-print 成模式当反例。无用行：去掉该行后覆盖不变。缺口是<strong>覆盖关系</strong>，不是词法。</p><p>与<a href="/cs/subtyping-variance">子类型</a>：开世界（可另编译新子类）不能穷尽；ADT 闭世界可以。OOP 的 visitor 穷尽靠密封类或默认方法。</p><h3 id="警告不是健全性定理" tabindex="-1">警告不是健全性定理 <a class="header-anchor" href="#警告不是健全性定理" aria-label="Permalink to &quot;警告不是健全性定理&quot;">​</a></h3><p>忽略警告仍可生成代码。依值类型里「穷尽」更强，后课点名。此处是代数数据类型上的模式覆盖。</p><p><span class="marginnote">Maranget 2007（JFP）。GHC <code>-Wincomplete-patterns</code>。本课不把 SMT 当穷尽引擎，尽管守卫里的布尔可用求解器辅助。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>空类型、空构造子、通配。递归：按列展开构造子，对每个构造子形成子矩阵。反例：沿失败边收集构造子前缀。守卫：保守当「可能失败」，故带守卫的子句不贡献穷尽——除非语言另有分析。</p>',11)),(a(),c(p,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%AD%90%E5%8F%A5%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20U%5B%22%E6%9C%89%E7%94%A8%E6%80%A7%22%5D%0A%20%20U%20--%3E%20EX%5B%22%E5%8F%8D%E4%BE%8B%E5%80%BC%E6%88%96%E7%A9%B7%E5%B0%BD%22%5D%0A%20%20U%20--%3E%20RED%5B%22%E6%97%A0%E7%94%A8%E5%AD%90%E5%8F%A5%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与错误恢复：不穷尽是类型/模式层诊断，不是语法 <code>error</code> 记号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数：构造子笛卡尔积。实用：按列剪枝、共享。记录模式、或模式（or-pattern）是覆盖的糖。可变与并发不在覆盖里：值在匹配中途被改是内存模型，后课。</p><p>不要用「加一个 <code>_</code>」当唯一建议而不展示反例；反例才教人补哪一枝。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GADT 细化后的不可达模式全文。后课默认：闭 ADT 可查穷尽与无用。下一课依值类型：穷尽可依赖值，检查变成证明。</p><p>也不把 Prolog 的子句搜索当穷尽性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>穷尽 = 不存在逃逸值；无用 = 覆盖不变。</li><li>闭的构造子世界可判定；开世界不能。</li><li>守卫使检查保守。</li><li>出处：Maranget, 2007；对照 Augustsson；Pierce TAPL case。</li></ul>',9))])}const g=s(h,[["render",_]]);export{T as __pageData,g as default};
